	 *
	 * @param      Criteria $criteria
	 * @param      PropelPDO $con
	 * @return     int The number of affected rows (if supported by underlying database driver).
	 */
	protected static function doOnDeleteCascade(Criteria $criteria, PropelPDO $con)
	{
		// initialize var to track total num of affected rows
		$affectedRows = 0;

		// first find the objects that are implicated by the $criteria
		$objects = Tb085PresupuestoPeer::doSelect($criteria, $con);
		foreach ($objects as $obj) {


			// delete related Tb097ModificacionDetalle objects
			$c = new Criteria(Tb097ModificacionDetallePeer::DATABASE_NAME);
			
			$c->add(Tb097ModificacionDetallePeer::ID_TB085_PRESUPUESTO, $obj->getId());
			$affectedRows += Tb097ModificacionDetallePeer::doDelete($c, $con);
		}
		return $affectedRows;
